"""M8: render the results tables used in README.md and paper/ from files in results/.

Usage: python scripts/m8_tables.py   -> results/tables.md
Every number in the README is copied from this file.
"""

from __future__ import annotations

import json

import pandas as pd

from kggc.utils import RESULTS_DIR

R = RESULTS_DIR


def ci(row, m):
    return f"{row[m]:.3f} ({row[m + '_lo']:.3f} to {row[m + '_hi']:.3f})"


def main() -> None:
    L = [
        "# Results tables",
        "",
        "Generated by `scripts/m8_tables.py` from files in `results/`. Do not edit by hand.",
        "",
    ]

    m1 = json.loads((R / "m1" / "summary.json").read_text())
    L += ["## M1. Temporal labels (ClinVar 2020-01 to 2026-11)", "", "| class | n |", "|---|---|"]
    L += [f"| {k} | {v:,} |" for k, v in m1["label_counts"].items()]
    L += [
        "",
        f"Downgrade rate among P/LP: {m1['downgrade_rate_among_PLP']:.3f}. Upgrade rate among VUS: {m1['upgrade_rate_among_VUS']:.3f}. Source: `results/m1/summary.json`.",
        "",
    ]

    m2 = json.loads((R / "m2" / "summary.json").read_text())
    L += [
        "## M2. Time-T graph",
        "",
        f"Nodes: {sum(m2['num_nodes'].values()):,} across {len(m2['num_nodes'])} types; edges: {sum(m2['num_edges'].values()):,} across {len(m2['num_edges'])} types. Source: `results/m2/summary.json`.",
        "",
    ]

    h1 = pd.read_csv(R / "m3" / "h1_main.csv")
    keep = [
        "stars", "n_submitters", "ever_conflicting_before_T", "gnomad_af", "cadd_phred", "gnn_rgcn", "gnn_hgt",
        "GBM prospective (fit on 2018 to 2020 revisions)", "GBM tabular", "GBM tabular + GNN (rgcn)",
        "GBM tabular + neighbour counts", "GBM tabular + neighbour counts + GNN (rgcn)", "GBM tabular + CADD (version unverified)",
    ]  # fmt: skip
    for task in ("downgrade", "upgrade"):
        t = h1[h1["task"] == task].set_index("method")
        first = t.iloc[0]
        L += [
            f"## M3 / H1: {task} (n = {int(first['n']):,}, positives = {int(first['n_pos']):,}, prevalence {first['prevalence']:.3f})",
            "",
            "| method | AUROC (95% CI) | AUPRC (95% CI) |",
            "|---|---|---|",
        ]
        for m in keep:
            if m in t.index:
                L.append(f"| {m} | {ci(t.loc[m], 'auroc')} | {ci(t.loc[m], 'auprc')} |")
        L.append("")
    dl = pd.read_csv(R / "m3" / "h1_deltas.csv")
    dl = dl[dl["metric"] == "auroc"]
    L += [
        "## M3 / H1: does the graph add signal? (paired bootstrap, AUROC)",
        "",
        "| task | baseline | with graph | delta (95% CI) | p |",
        "|---|---|---|---|---|",
    ]
    for r in dl.itertuples():
        L.append(
            f"| {r.task} | {r.baseline} | {r.with_graph} | {r.delta:+.4f} ({r.lo:+.4f} to {r.hi:+.4f}) | {r.p_boot:.3f} |"
        )
    L.append("")
    for tag in ("rgcn", "hgt"):
        p = R / "m3" / f"conformal_{tag}.json"
        if p.exists():
            c = json.loads(p.read_text())
            L.append(
                f"Conformal ({tag}, alpha {c['alpha']}): coverage P/LP {c['coverage_plp']:.3f}, B/LB {c['coverage_blb']:.3f}."
            )
    for tag in ("rgcn", "hgt"):
        p = R / "m3" / f"{tag}_linkpred_metrics.csv"
        if p.exists():
            m = pd.read_csv(p)
            L.append(
                f"Time-T link prediction ({tag}, 5 held-out folds): P/LP vs B/LB AUROC {m['test_auc_plp_vs_blb'].min():.3f} to {m['test_auc_plp_vs_blb'].max():.3f}."
            )
    L.append("")

    q = json.loads((R / "qiagen_20" / "stats.json").read_text())
    q2 = json.loads((R / "qiagen_20_asof_2020-01-01" / "stats.json").read_text())
    b = json.loads((R / "m4_broad" / "summary.json").read_text())
    L += [
        "## M4. Variant dossier",
        "",
        "| set | complete | sentences | citations | citation validity | claim-record agreement |",
        "|---|---|---|---|---|---|",
    ]
    L.append(
        f"| QIAGEN 20 (latest) | {q['n_complete']}/{q['n_variants']} | {q['n_claims']} | {q['n_citations']} | {q['citation_validity_rate']:.3f} | 1.000 |"
    )
    L.append(
        f"| QIAGEN 20 (as of 2020-01-01) | {q2['n_complete']}/{q2['n_variants']} | {q2['n_claims']} | {q2['n_citations']} | {q2['citation_validity_rate']:.3f} | 1.000 |"
    )
    for k in ("expert", "gwas", "conflict"):
        s = b[k]
        L.append(
            f"| {k} (n={s['n_variants']}) | {s['n_complete']}/{s['n_variants']} | {s['n_claims']} | {s['n_citations']} | {s['citation_validity_rate']:.3f} | {s['claim_record_agreement_rate']:.3f} |"
        )
    cd = b["conflict_detection"]
    L += [
        "",
        f"Conflict recall against ClinVar's conflicting flag (n={cd['n_positives_with_ClinVar_conflicting_flag']}): {cd['recall_from_submissions_only']:.2f} from individual submissions alone. Submitter disagreement on the expert-panel set: {cd['submitter_disagreement_rate_on_expert_panel_set']:.2f}. Haplotype pairs detected in the QIAGEN set: {q['haplotype_pairs']}.",
        "",
    ]

    p = R / "m5" / "ablation_summary.csv"
    if p.exists():
        a = pd.read_csv(p)
        s5 = json.loads((R / "m5" / "summary.json").read_text())
        names = {
            "a": "(a) GNN only, conformal rule",
            "b0": "LLM alone, no tools",
            "b": "(b) agent without GNN tools",
            "c": "(c) agent with GNN tools",
            "d": "(d) agent with GNN tools + conformal budget",
        }
        L += [
            f"## M5 / H2: audit agent ({s5['model']}, n = {s5['n_edges']} edges, balanced over the four outcomes)",
            "",
            "| config | accuracy | macro-F1 | coverage | accuracy when decided | ECE | tool calls / edge | prompt tokens / edge |",
            "|---|---|---|---|---|---|---|---|",
        ]
        for r in a.itertuples():
            L.append(
                f"| {names.get(r.config, r.config)} | {r.accuracy:.3f} | {r.macro_f1:.3f} | {r.coverage:.3f} | {r.accuracy_on_decided:.3f} | {r.ece:.3f} | {r.tool_calls_per_edge:.2f} | {r.prompt_tokens_per_edge:,.0f} |"
            )
        L.append("")

    p = R / "m6" / "cleaning_summary.csv"
    if p.exists():
        cs = pd.read_csv(p, header=[0, 1], index_col=0)
        L += [
            "## M6 / H3: cleaning and downstream gene-disease link prediction (prospective, 2026 pairs)",
            "",
            "| arm | edges removed | AUROC mean (sd) | AUPRC mean (sd) | hits@1 of 11 mean (sd) |",
            "|---|---|---|---|---|",
        ]
        for arm in ["original", "gnn_flag", "downweight", "gbm_prosp", "random", "oracle"]:
            if arm in cs.index:
                r = cs.loc[arm]
                L.append(
                    f"| {arm} | {r[('n_removed', 'mean')]:.0f} | {r[('auroc', 'mean')]:.4f} ({r[('auroc', 'std')]:.4f}) | {r[('auprc', 'mean')]:.4f} ({r[('auprc', 'std')]:.4f}) | {r[('hits_at_1_of_11', 'mean')]:.4f} ({r[('hits_at_1_of_11', 'std')]:.4f}) |"
                )
        L.append("")
    p = R / "m6_stark" / "coverage.json"
    if p.exists():
        c = json.loads(p.read_text())
        L += [
            f"PrimeKG trust transfer: {c['edges_with_clinvar_support_at_T']:,} of {c['primekg_disease_protein_edges']:,} disease-protein edges have time-T ClinVar support; {c['edges_with_trust_below_0.5']:,} have trust below 0.5. STaRK-Prime G-Retriever: not run (needs GPU).",
            "",
        ]

    p = R / "m7" / "summary.json"
    if p.exists():
        c = json.loads(p.read_text())
        L += [
            "## M7. COPD / emphysema",
            "",
            f"GWAS Catalog associations retrieved: {c['n_associations']:,} ({c['n_genome_wide_significant']:,} genome-wide significant, {c['n_lead_loci']} lead loci). COPD-related ClinVar edges at T: {c['n_copd_edges']} ({c['copd_edges_by_label']}).",
            "",
        ]
        if "agent" in c:
            L.append(
                f"Audit agent on these edges: accuracy {c['agent']['accuracy']:.2f} (n={c['agent']['n']})."
            )
            L.append("")
    (R / "tables.md").write_text("\n".join(L) + "\n")
    print("\n".join(L))


if __name__ == "__main__":
    main()
